import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import 'package:introduction_screen/introduction_screen.dart';import '../../../../Core/Resources/app_colors.dart';import '../../../../Core/Resources/app_fonts.dart';PageViewModel buildPageViewModel({  required String title,  required String body,  required String image,}) {  return PageViewModel(    titleWidget: Column(      mainAxisAlignment: MainAxisAlignment.center,      children: [        Text(          title,          textAlign: TextAlign.center,          style: AppTextStyles.h4Bold.copyWith(color: AppColors.backgroundColor),        ),        SizedBox(height: 10.h),        Text(          body,          textAlign: TextAlign.center,          style:              AppTextStyles.bodyMediumSemiBold.copyWith(color: Colors.white70),        ),      ],    ),    bodyWidget: const SizedBox(),    image: _buildBackgroundImage(image),    decoration: _pageDecoration(),  );}PageDecoration _pageDecoration() {  return const PageDecoration(    fullScreen: true,    bodyFlex: 0,    imagePadding: EdgeInsets.zero,    contentMargin: EdgeInsets.zero,  );}Widget _buildBackgroundImage(String assetName) {  return Stack(    fit: StackFit.expand,    children: [      Image.asset(        assetName,        width: double.infinity,        height: double.infinity,        fit: BoxFit.cover,      ),      Container(        color: Colors.black.withAlpha((0.3 * 255).toInt()),      ),    ],  );}